import java.util.*;
import java.io.*;

public class Main {
    static class MaxFlow {
        int n;
        List<int[]>[] adj;
        int[] level;
        int[] iter;

        @SuppressWarnings("unchecked")
        public MaxFlow(int n) {
            this.n = n;
            adj = new ArrayList[n];
            for (int i = 0; i < n; i++) {
                adj[i] = new ArrayList<>();
            }
        }

        public void addEdge(int u, int v, int cap) {
            adj[u].add(new int[]{v, cap, adj[v].size()});
            adj[v].add(new int[]{u, 0, adj[u].size() - 1});
        }

        void bfs(int s) {
            level = new int[n];
            Arrays.fill(level, -1);
            level[s] = 0;
            Queue<Integer> queue = new LinkedList<>();
            queue.offer(s);
            while (!queue.isEmpty()) {
                int v = queue.poll();
                for (int[] e : adj[v]) {
                    int to = e[0], cap = e[1], rev = e[2];
                    if (cap > 0 && level[to] < 0) {
                        level[to] = level[v] + 1;
                        queue.offer(to);
                    }
                }
            }
        }

        int dfs(int v, int t, int f) {
            if (v == t) return f;
            for (; iter[v] < adj[v].size(); iter[v]++) {
                int[] e = adj[v].get(iter[v]);
                int to = e[0], cap = e[1], rev = e[2];
                if (cap > 0 && level[v] < level[to]) {
                    int d = dfs(to, t, Math.min(f, cap));
                    if (d > 0) {
                        adj[v].get(iter[v])[1] -= d;
                        adj[to].get(rev)[1] += d;
                        return d;
                    }
                }
            }
            return 0;
        }

        int maxFlow(int s, int t) {
            int flow = 0;
            while (true) {
                bfs(s);
                if (level[t] < 0) return flow;
                iter = new int[n];
                while (true) {
                    int f = dfs(s, t, Integer.MAX_VALUE);
                    if (f == 0) break;
                    flow += f;
                }
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st;

        int N = Integer.parseInt(br.readLine());
        int M = 3;
        int[] A = new int[M];
        int[] B = new int[M];

        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) {
            A[i] = Integer.parseInt(st.nextToken());
        }
        st = new StringTokenizer(br.readLine());
        for (int i = 0; i < M; i++) {
            B[i] = Integer.parseInt(st.nextToken());
        }

        int initialSum = 0;
        for (int i = 0; i < M; i++) {
            initialSum += Math.min(A[i], B[(i + 1) % M]);
        }

        MaxFlow mf = new MaxFlow(2 * M + 2);
        int s = 2 * M;
        int t = 2 * M + 1;

        for (int i = 0; i < M; i++) {
            mf.addEdge(s, i, N);
            mf.addEdge(M + i, t, B[i]);
            mf.addEdge(i, M + i, A[i]);
            mf.addEdge(i, M + ((i - 1 + M) % M), A[i]);
        }

        int maxFlowValue = mf.maxFlow(s, t);
        int result = N - maxFlowValue;

        System.out.println(result + " " + initialSum);
    }
}
